import{_ as a,o as i,c as s,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Creación de personajes y trasfondos","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/characters/character-creation.md","filePath":"es/guide/characters/character-creation.md"}'),n={name:"es/guide/characters/character-creation.md"};function t(o,e,c,d,l,p){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="character-creation-backgrounds" tabindex="-1">Creación de personajes y trasfondos <a class="header-anchor" href="#character-creation-backgrounds" aria-label="Enlace permanente a &quot;Creación de personajes y trasfondos&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Son cambios previstos, no reglas confirmadas del juego disponible. <strong>Implementación/disponibilidad:</strong> no acreditada para este rediseño. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-08 frente a la <a href="/Syrolands-Public/es/game-design/characters/character-creation.html">especificación completa</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Un trasfondo aporta competencias iniciales y conocimientos, no una clase permanente.</li><li>Los fundamentos iniciales cerca de habilidad 20 son ilustrativos; los paquetes y reglas de cambio siguen abiertos.</li><li>Aprende otras disciplinas con maestros, práctica y descubrimiento.</li></ul><h2 id="a-starting-history-not-a-class" tabindex="-1">Una historia inicial, no una clase <a class="header-anchor" href="#a-starting-history-not-a-class" aria-label="Enlace permanente a &quot;Una historia inicial, no una clase&quot;">​</a></h2><p>El modelo propuesto combina un trasfondo, competencias iniciales y conocimientos de partida. Tu historia te da un comienzo útil sin fijar tu dirección futura.</p><p>Una competencia inicial importante podría empezar cerca de habilidad 20, con sus fundamentos ya conocidos, omitiendo la primera instrucción con un maestro. Los valores exactos y el número de elecciones no son definitivos.</p><h2 id="possible-histories" tabindex="-1">Posibles historias <a class="header-anchor" href="#possible-histories" aria-label="Enlace permanente a &quot;Posibles historias&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ejemplo</th><th>Posible dirección inicial</th></tr></thead><tbody><tr><td>Aprendiz de cazador</td><td>Archery, Tracking, Animal Lore y preparación básica de piezas cazadas</td></tr><tr><td>Aprendiz de taller</td><td>Carpentry, Tinkering y ensamblajes básicos</td></tr><tr><td>Sanador de aldea</td><td>Healing, Anatomy y conocimientos médicos básicos</td></tr></tbody></table><p>Son ejemplos, no opciones iniciales confirmadas. No prometen objetos de partida, reputación ni todas las técnicas asociadas a una habilidad.</p><h2 id="your-next-steps-remain-open" tabindex="-1">Tus siguientes pasos siguen abiertos <a class="header-anchor" href="#your-next-steps-remain-open" aria-label="Enlace permanente a &quot;Tus siguientes pasos siguen abiertos&quot;">​</a></h2><p>Deberías poder abordar otras disciplinas mediante <a href="/Syrolands-Public/es/guide/characters/skills.html#learning-skills-and-finding-teachers">maestros y práctica</a>, y descubrir <a href="/Syrolands-Public/es/guide/characters/techniques.html">técnicas</a> independientemente del valor de habilidad. Los trasfondos deben explicar una identidad inicial sin convertirse en restricciones de clase permanentes.</p><p>Los atributos iniciales, paquetes exactos, reglas de reconfiguración y tratamiento de personajes existentes siguen sin resolver. Se están reconsiderando los <a href="/Syrolands-Public/es/guide/characters/stats.html">atributos</a> para que un personaje inicial responda con agilidad.</p>',13)])])}const m=a(n,[["render",t]]);export{u as __pageData,m as default};
